// testGenesisOnce ensures genesis tests only initialize the library once.
// Each test that creates genesis data should call this first.
var testGenesisOnce sync.Once

func initGenesisTestOnce() {
	testGenesisOnce.Do(func() {
		ledger.ResetForTesting()
	})
}

func TestBuildGenesisSnapshotData_Basic(t *testing.T) {
	initGenesisTestOnce()
	ledger.ResetForTesting()

	// Generate a test private key
	_, privateKey, err := ed25519.GenerateKey(nil)
	require.NoError(t, err)

	genesisTime := uint32(time.Now().Unix())

	data, err := BuildGenesisSnapshotData(privateKey, genesisTime, "test ledger")
	require.NoError(t, err)
	require.NotNil(t, data)

	// Verify identity
	require.NotNil(t, data.Identity)
	require.Equal(t, genesisTime, data.Identity.GenesisTimeUnix)
	require.Equal(t, "test ledger", data.Identity.Description)

	// Verify library YAML is set
	require.NotEmpty(t, data.LibraryYAML)

	// Verify constants are parsed
	require.NotNil(t, data.Constants)
	require.Equal(t, uint64(ledger.DefaultInitialSupply), data.Constants.InitialSupply)

	// Verify branch ID is at slot 0
	require.Equal(t, uint32(0), data.BranchID.Slot())

	// Verify root record
	require.NotNil(t, data.RootRecord.Root)
	require.Equal(t, uint64(ledger.DefaultInitialSupply), data.RootRecord.Supply)
	require.Equal(t, uint64(ledger.DefaultInitialSupply), data.RootRecord.CoverageDelta)
	require.Equal(t, uint64(ledger.DefaultInitialSupply), data.RootRecord.SlotInflation)

	// Verify store is populated
	require.NotNil(t, data.Store)
	require.Greater(t, data.Store.Len(), 0)

	// Verify bootstrap chain ID
	require.Equal(t, base.BoostrapSequencerID, data.BootstrapChainID)
}

