func TestBuildGenesisSnapshotData_InvalidPrivateKey(t *testing.T) {
	ledger.ResetForTesting()

	// Too short private key
	shortKey := make([]byte, 16)
	_, err := BuildGenesisSnapshotData(shortKey, uint32(time.Now().Unix()), "")
	require.Error(t, err)
	require.Contains(t, err.Error(), "invalid private key size")

	// Too long private key
	longKey := make([]byte, 128)
	_, err = BuildGenesisSnapshotData(longKey, uint32(time.Now().Unix()), "")
	require.Error(t, err)
}

func TestBuildGenesisSnapshotData_UpgradeLibraryStored(t *testing.T) {
	ledger.ResetForTesting()

	_, privateKey, err := ed25519.GenerateKey(nil)
	require.NoError(t, err)

	data, err := BuildGenesisSnapshotData(privateKey, uint32(time.Now().Unix()), "")
	require.NoError(t, err)

	// Verify upgrade library is stored at slot 0
	yaml, found := GetUpgradeLibraryDirect(data.Store, 0)
	require.True(t, found)
	require.Equal(t, data.LibraryYAML, yaml)

	// Verify it's the only upgrade library
	count := CountUpgradeLibraries(data.Store)
	require.Equal(t, 1, count)
}

func TestBuildGenesisSnapshotData_ThreeOutputs(t *testing.T) {
	ledger.ResetForTesting()

	_, privateKey, err := ed25519.GenerateKey(nil)
	require.NoError(t, err)

	data, err := BuildGenesisSnapshotData(privateKey, uint32(time.Now().Unix()), "")
	require.NoError(t, err)

	// Read the state
	rdr := MustNewReadable(data.Store, data.RootRecord.Root)

	// Verify all 3 UTXOs exist
	// Note: IterateUTXOIDs only counts UTXOs in the accounts partition,
	// but upgrade UTXOs are not indexed there (they don't have parseable locks).
	// So we verify each UTXO individually using HasUTXO.

	// Verify genesis output exists
	genesisOid := base.GenesisOutputID()
	require.True(t, rdr.HasUTXO(genesisOid), "genesis output should exist")

	// Verify stem output exists
	stemOid := base.GenesisStemOutputID()
	require.True(t, rdr.HasUTXO(stemOid), "stem output should exist")

	// Verify upgrade UTXO exists
	upgradeOid := base.UpgradeOutputID(0)
	require.True(t, rdr.HasUTXO(upgradeOid), "upgrade UTXO should exist")
}

func TestWriteGenesisSnapshot_RoundTrip(t *testing.T) {
	ledger.ResetForTesting()

	// Create temp directory
	tmpDir, err := os.MkdirTemp("", "genesis_snapshot_test")
	require.NoError(t, err)
	defer os.RemoveAll(tmpDir)

	// Generate test data
	_, privateKey, err := ed25519.GenerateKey(nil)
	require.NoError(t, err)

	genesisTime := uint32(time.Now().Unix())

	// Build and write snapshot
	fpath, data, err := CreateGenesisSnapshot(privateKey, genesisTime, "round trip test", tmpDir)
	require.NoError(t, err)
	require.FileExists(t, fpath)

	// Verify file name format
	require.True(t, filepath.Ext(fpath) == ".snapshot" ||
		len(filepath.Base(fpath)) > len(".snapshot"))

	// Read back the snapshot
	stream, err := OpenSnapshotFileStream(fpath)
	require.NoError(t, err)
	defer stream.Close()

	// Verify header
	require.Equal(t, snapshotFormatVersionString, stream.Header.Version)

	// Verify upgrade libraries (identity is now part of the library YAML)
	require.Len(t, stream.UpgradeLibraries, 1)
	require.Equal(t, uint32(0), stream.UpgradeLibraries[0].Slot)
	require.Equal(t, data.LibraryYAML, stream.UpgradeLibraries[0].LibraryYAML)

	// Verify branch ID
	require.Equal(t, data.BranchID, stream.BranchID)

	// Verify we can parse constants
	constants, err := stream.GetLedgerConstants()
	require.NoError(t, err)
	require.Equal(t, data.Constants.InitialSupply, constants.InitialSupply)
}

