func TestGenesisSnapshotData_DeterministicOutput(t *testing.T) {
	// Same private key and genesis time should produce same results
	seed := make([]byte, 32)
	for i := range seed {
		seed[i] = byte(i)
	}
	privateKey := ed25519.NewKeyFromSeed(seed)
	genesisTime := uint32(1704067200) // Fixed time

	ledger.ResetForTesting()
	data1, err := BuildGenesisSnapshotData(privateKey, genesisTime, "deterministic test")
	require.NoError(t, err)

	ledger.ResetForTesting()
	data2, err := BuildGenesisSnapshotData(privateKey, genesisTime, "deterministic test")
	require.NoError(t, err)

	// Compare key fields
	require.Equal(t, data1.Identity.GenesisTimeUnix, data2.Identity.GenesisTimeUnix)
	require.Equal(t, data1.Identity.Description, data2.Identity.Description)
	require.Equal(t, data1.BranchID, data2.BranchID)
	require.Equal(t, data1.BootstrapChainID, data2.BootstrapChainID)
	require.Equal(t, data1.RootRecord.Supply, data2.RootRecord.Supply)
	require.Equal(t, data1.LibraryYAML, data2.LibraryYAML)

	// Root commitments should be equal
	require.Equal(t, data1.RootRecord.Root.Bytes(), data2.RootRecord.Root.Bytes())
}
